// E73 · CC#1 · un flujo que muere le avisa a alguien.
// E79 · FRENO al ruido: un aviso por (flujo + nodo) cada 10 minutos.
// E81 · CC#1 · 2026-09-17 · EL FRENO YA NO SE CALLA EN FALSO: este nodo solo LEE la memoria y decide;
// la marca «avisado» la pone el Cierre, y SOLO cuando Slack confirmo ok:true (E80 · CC#2 midio que
// un aviso rechazado por Slack abria 10 min de silencio en verde). Los suprimidos se guardan con
// corrida y motivo (para saber quien) y se declaran con su lapso real, en el proximo aviso que
// SI llegue, sean del mismo paso o de otro.
const e = $input.first().json || {};
// E101 · una nota perdida (la corrida SIGUE) llega por la segunda entrada · mismo freno, otro título.
const nota = e.nota_perdida === true;
const ex = e.execution || {};
const wf = e.workflow || {};
const err = (ex.error || {});
const base = ($env.N8N_BASE_URL || 'https://n8n-production-72be.up.railway.app').replace(/\/+$/, '');
const url = ex.url || (base + '/workflow/' + (wf.id || '?') + '/executions/' + (ex.id || '?'));
const nodo = (err.node && err.node.name) || ex.lastNodeExecuted || '(sin nodo)';
const mensaje = String(err.message || err.description || 'sin mensaje').slice(0, 600);
const modo = ex.mode || '?';
const ahora = Date.now();
const cuando = new Date(ahora).toISOString();

const VENTANA_MS = 10 * 60 * 1000;
const clave = String(wf.id || '?') + '::' + nodo;
let suprimido = false;
let pendientes = [];   // suprimidos de TODOS los pasos, aun sin declarar
try {
  const mem = $getWorkflowStaticData('global');
  mem.freno = mem.freno || {};
  const reg = mem.freno[clave] || { ultimo_confirmado: 0, suprimidos: [] };
  if (!Array.isArray(reg.suprimidos)) reg.suprimidos = [];
  if (ahora - (reg.ultimo_confirmado || 0) < VENTANA_MS) {
    // dentro de la ventana de un aviso que SI llego: se suprime, pero queda quien y cuando
    suprimido = true;
    reg.suprimidos.push({ t: ahora, corrida: ex.id || null, flujo: wf.name || wf.id || '?', nodo: nodo, motivo: mensaje.slice(0, 120) });
    if (reg.suprimidos.length > 30) reg.suprimidos = reg.suprimidos.slice(-30);
  }
  mem.freno[clave] = reg;
  // pendientes de declarar (de cualquier paso) · se limpian en el Cierre solo cuando Slack confirma
  for (const k of Object.keys(mem.freno)) for (const s of (mem.freno[k].suprimidos || [])) pendientes.push(s);
  pendientes.sort(function (a, b) { return a.t - b.t; });
} catch (e2) {
  suprimido = false;  // sin memoria: se AVISA (mejor ruido que silencio)
}

const hhmm = function (t) { return new Date(t).toISOString().slice(0, 16).replace('T', ' ') + ' UTC'; };
let declarados = '';
if (!suprimido && pendientes.length) {
  const desde = hhmm(pendientes[0].t), hasta = hhmm(pendientes[pendientes.length - 1].t);
  declarados = pendientes.length + ' fallo(s) suprimido(s) por el freno entre ' + desde + ' y ' + hasta + ':\n'
    + pendientes.slice(-8).map(function (s) { return '• corrida ' + s.corrida + ' · ' + s.flujo + ' · nodo «' + s.nodo + '» · ' + s.motivo; }).join('\n')
    + (pendientes.length > 8 ? '\n• … y ' + (pendientes.length - 8) + ' más (en la memoria del avisador)' : '');
}

return [{ json: {
  workflow_id: wf.id || null,
  workflow_name: wf.name || '(sin nombre)',
  execution_id: ex.id || null,
  execution_url: url,
  nodo_que_murio: nodo,
  modo: modo,
  mensaje: mensaje,
  cuando: cuando,
  suprimido: suprimido,
  nota_perdida: nota,
  clave_freno: clave,
  pendientes_declarados: suprimido ? 0 : pendientes.length,
  declarados: declarados,
  titulo: (nota ? 'SE PERDIÓ UNA NOTA · la corrida SIGUE · ' : 'MURIÓ UNA CORRIDA · ') + (wf.name || wf.id || '?') + ' · nodo «' + nodo + '»' + (!suprimido && pendientes.length ? ' · +' + pendientes.length + ' suprimido(s) declarados abajo' : ''),
} }];

// E73 · el aviso no depende de que el aviso llegue · patrón E63/E68.
// E81 · CC#1 · 2026-09-17 · AQUI se anota «avisado» en la memoria del freno, y SOLO si Slack confirmo
// ok:true. Si Slack no confirma, NO se anota: la proxima muerte del mismo paso vuelve a intentar avisar
// en vez de callar 10 minutos en verde (E80 · CC#2). Los suprimidos declarados en este aviso se limpian
// tambien aqui, solo si el aviso llego.
const a = $('Armar el aviso').first().json || {};
const respuestas = $input.all().map(function (i) { return i.json || {}; });
const confirmadas = respuestas.filter(function (r) { return r.ok === true; });
if (respuestas.length === 0 || confirmadas.length !== respuestas.length) {
  const r = respuestas.find(function (x) { return x.ok !== true; }) || {};
  const causa = r.error
    ? (typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)))
    : (respuestas.length === 0 ? 'Slack no devolvio respuesta' : 'Slack no confirmo ok:true · ' + JSON.stringify(r).slice(0, 200));
  throw new Error('[aviso-de-error] el aviso NO llego a #alertas · ' + String(causa).slice(0, 300) + ' · murio ' + a.workflow_name + ' · corrida ' + a.execution_id + ' · el freno NO se marca: la proxima muerte vuelve a avisar');
}
try {
  const mem = $getWorkflowStaticData('global');
  mem.freno = mem.freno || {};
  const reg = mem.freno[a.clave_freno] || { ultimo_confirmado: 0, suprimidos: [] };
  reg.ultimo_confirmado = Date.now();
  mem.freno[a.clave_freno] = reg;
  // los suprimidos ya declarados en este aviso (de todos los pasos) se limpian
  for (const k of Object.keys(mem.freno)) { mem.freno[k].suprimidos = []; }
  // limpieza: pasos sin actividad en 1 dia
  for (const k of Object.keys(mem.freno)) { if (Date.now() - (mem.freno[k].ultimo_confirmado || 0) > 86400000 && !(mem.freno[k].suprimidos || []).length) delete mem.freno[k]; }
} catch (e2) { /* sin memoria no hay freno · ya se aviso */ }
console.log('[aviso-de-error] aviso confirmado por Slack · ts ' + confirmadas[0].ts + ' · ' + a.workflow_name + ' · corrida ' + a.execution_id + ' · freno marcado');
return [{ json: Object.assign({}, a, { aviso_ts: confirmadas[0].ts, aviso_canal: confirmadas[0].channel, freno_marcado: true }) }];

// E79 · el aviso suprimido por el freno TAMBIÉN deja rastro: queda en el registro del motor,
// con el mismo detalle, y se cuenta para el próximo aviso de ese flujo+nodo.
const v = $input.first().json;
console.log('[aviso-de-error] SUPRIMIDO por freno (1 aviso por flujo+nodo cada 10 min) · ' + v.workflow_name + ' · corrida ' + v.execution_id + ' · nodo ' + v.nodo_que_murio);
return [{ json: v }];
